            const operator = expr[pos];
            pos++;
            const right = parseTerm();
            if (operator === '+') {
                result += right;
            } else {
                result -= right;
            }
        }

        return result;
    }

    function parseTerm() {
        let result = parseFactor();

        while (expr[pos] === '*' || expr[pos] === '/') {
            const operator = expr[pos];
            pos++;
            const right = parseFactor();
            if (operator === '*') {
                result *= right;
            } else {
                if (right === 0) {
                    throw new Error('Division by zero');
                }
                result /= right;
            }
        }

        return result;
    }

    function parseFactor() {
        if (expr[pos] === '-') {
            pos++;
            return -parseFactor();
        }

        if (expr[pos] === '(') {
            pos++;
            const result = parseExpression();
            if (expr[pos] !== ')') {
